[183] = {183, "backrub_ui_tips1", "Follow\u{0020}the\u{0020}designated\u{0020}route\u{0020}and\u{0020}apply\u{0020}soap\u{0020}to\u{0020}the\u{0020}driver!\nThe\u{0020}correct\u{0020}route\u{0020}will\u{0020}maximize\u{0020}the\u{0020}efficiency\u{0020}of\u{0020}the\u{0020}soap~", "0", "0", "沿着规定好的路线，为驾驶员打上肥皂吧！\n正确的路线，能最大效率的利用肥皂~", "0"},
[184] = {184, "backrub_ui_tips2", "The\u{0020}shorter\u{0020}the\u{0020}completion\u{0020}time,\u{0020}the\u{0020}higher\u{0020}the\u{0020}score.", "0", "0", "完成时间越短，评分越高", "0"},
[185] = {185, "backrub_ui_tips3", "Since\u{0020}you\u{0020}are\u{0020}fighting\u{0020}in\u{0020}the\u{0020}ocean,\u{0020}occasionally\u{0020}creatures\u{0020}living\u{0020}there\u{0020}will\u{0020}cling\u{0020}to\u{0020}the\u{0020}driver.\u{0020}\nClick\u{0020}the\u{0020}screen\u{0020}at\u{0020}the\u{0020}right\u{0020}moment\u{0020}to\u{0020}help\u{0020}the\u{0020}driver\u{0020}get\u{0020}rid\u{0020}of\u{0020}the\u{0020}animals!", "0", "0", "因在海洋作战，偶尔会有栖息于此的生物挂在驾驶员身上，\n看准时机点击屏幕按钮，帮助驾驶员赶走身上的动物吧！", "0"},
[186] = {186, "backrub_ui_tips4", "Choose\u{0020}the\u{0020}most\u{0020}suitable\u{0020}skincare\u{0020}product\u{0020}for\u{0020}the\u{0020}driver.\u{0020}Drivers\u{0020}from\u{0020}different\u{0020}regions\u{0020}require\u{0020}different\u{0020}skincare\u{0020}products.\nCarefully\u{0020}check\u{0020}each\u{0020}question\u{0020}to\u{0020}select\u{0020}the\u{0020}most\u{0020}appropriate\u{0020}product\u{0020}for\u{0020}the\u{0020}driver~", "0", "0", "为驾驶员挑选最合适的护肤品吧，不同地区的驾驶员适用的护肤品也不同，\n仔细看好每个问题，才能选出最适合驾驶员的那一款~", "0"},
[187] = {187, "backrub_ui_tips5", "The\u{0020}more\u{0020}questions\u{0020}you\u{0020}answer\u{0020}correctly,\u{0020}the\u{0020}more\u{0020}suitable\u{0020}the\u{0020}selected\u{0020}skincare\u{0020}product\u{0020}will\u{0020}be.\nDon’t\u{0020}choose\u{0020}the\u{0020}wrong\u{0020}skincare\u{0020}product,\u{0020}as\u{0020}the\u{0020}effects\u{0020}of\u{0020}different\u{0020}products\u{0020}vary~", "0", "0", "答对的题目越多，选择的护肤品就越合适，\n可不要选错护肤品哦，不同的护肤品，保养的功效也不同~", "0"},
