[242] = {242, "battlepause_ui_tips5", "\"Resonant\u{0020}Gear\"\u{0020}has\u{0020}been\u{0020}unlocked,\u{0020}returning\u{0020}to\u{0020}the\u{0020}main\u{0020}screen\u{0020}to\u{0020}start\u{0020}the\u{0020}tutorial.", "0", "0", "\"共鸣装备\"已解锁,即将返回主界面开启教程。", "0"},
