[2510] = {2510, "ui_return_text2", "Finally\u{0020}got\u{0020}in\u{0020}touch...!!\nBrother,\u{0020}are\u{0020}you\u{0020}okay\u{0020}now?\u{0020}Are\u{0020}you\u{0020}hurt?\u{0020}Have\u{0020}you\u{0020}been\u{0020}eating\u{0020}properly\u{0020}all\u{0020}this\u{0020}time?\u{0020}Gia\u{0020}knows\u{0020}that\u{0020}this\u{0020}secret\u{0020}mission\u{0020}was\u{0020}arranged\u{0020}by\u{0020}Mom\u{0020}and\u{0020}she\u{0020}demanded\u{0020}that\u{0020}you\u{0020}keep\u{0020}it\u{0020}strictly\u{0020}confidential,\u{0020}not\u{0020}telling\u{0020}anyone.\u{0020}So\u{0020}Gia\u{0020}won't\u{0020}ask\u{0020}too\u{0020}many\u{0020}questions,\u{0020}nor\u{0020}will\u{0020}she\u{0020}pry,\u{0020}please\u{0020}rest\u{0020}assured,\u{0020}brother.\u{0020}But\u{0020}if\u{0020}there's\u{0020}a\u{0020}next\u{0020}time—Gia\u{0020}is\u{0020}just\u{0020}saying\u{0020}if!\u{0020}It's\u{0020}just\u{0020}a\u{0020}hypothetical,\u{0020}okay!\nIf\u{0020}Mom\u{0020}asks\u{0020}you\u{0020}to\u{0020}do\u{0020}something\u{0020}similar\u{0020}again,\u{0020}could\u{0020}you\u{0020}let\u{0020}Gia\u{0020}know\u{0020}before\u{0020}you\u{0020}leave?\u{0020}Please\u{0020}don't\u{0020}just\u{0020}disappear\u{0020}again...\u{0020}%s\u{0020}days,\u{0020}there\u{0020}are\u{0020}a\u{0020}total\u{0020}of\u{0020}%s\u{0020}days.\u{0020}Gia\u{0020}couldn't\u{0020}get\u{0020}in\u{0020}touch\u{0020}with\u{0020}you,\u{0020}and\u{0020}being\u{0020}alone\u{0020}in\u{0020}the\u{0020}Danube\u{0020}was\u{0020}really\u{0020}scary...\u{0020}Oh,\u{0020}and\u{0020}by\u{0020}the\u{0020}way.\u{0020}During\u{0020}the\u{0020}time\u{0020}you\u{0020}were\u{0020}out\u{0020}of\u{0020}contact,\u{0020}drivers\u{0020}from\u{0020}all\u{0020}over\u{0020}were\u{0020}very\u{0020}concerned\u{0020}about\u{0020}your\u{0020}whereabouts\u{0020}and\u{0020}often\u{0020}called\u{0020}to\u{0020}ask\u{0020}about\u{0020}your\u{0020}recent\u{0020}situation.\u{0020}Should\u{0020}Gia\u{0020}synchronize\u{0020}the\u{0020}news\u{0020}that\u{0020}you're\u{0020}about\u{0020}to\u{0020}return\u{0020}to\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}with\u{0020}them?\u{0020}Or\u{0020}would\u{0020}you\u{0020}rather\u{0020}tell\u{0020}them\u{0020}yourself?", "0", "0", "终于联系上了……！！\n哥哥你现在还好吗？没有受伤吧？这段时间有好好吃饭吗？吉雅知道，这次秘密行动是妈妈安排的，并且要求哥哥严格保密，不可以告诉任何人。所以吉雅不会多问，更不会追问，请哥哥放心啦。但如果有下次——吉雅是说如果！只是一个假设哦！\n如果以后妈妈又让哥哥做相类似的事情，可不可以在离开之前，和吉雅说一声？不要再突然消失不见了……%s天，一共有%s天呢。吉雅联系不上哥哥，一个人在多瑙，真的很害怕……啊，对了。在哥哥失联的这段时间里，各地的驾驶员们也都对哥哥的去向非常关心，时常来电询问你的近况。需要吉雅将您即将返回多瑙支部的消息同步给她们吗？还是说，哥哥更想自己亲口告诉她们？", "0"},
[2511] = {2511, "ui_return_text3", "Gia\u{0020}prepared\u{0020}the\u{0020}supplies,\u{0020}they\u{0020}should\u{0020}all\u{0020}be\u{0020}things\u{0020}you'll\u{0020}need~", "0", "0", "吉雅准备的物资，应该都是哥哥用得上的~", "0"},
[2512] = {2512, "ui_return_text4", "The\u{0020}love\u{0020}of\u{0020}family", "0", "0", "吉雅准备的物资，应该都是哥哥用得上的~", "0"},
[2513] = {2513, "ui_dmm_login1", "データ連携", "0", "0", "0", "0"},
[2514] = {2514, "ui_dmm_login2", "すでにハツリバーブ-HAZEREVERB-をプレイしている場合は\n<color=#ED6A47>データ連携</color>を選択してください\n以前のゲームデータと連携してプレイすることができます\n<color=#ED6A47>異なるOS</color>にデータ連携した場合、<color=#ED6A47>連携前のOS</color>で所持していた\n<color=#ED6A47>原初結晶は連携後のOSでは使用できません</color>\n連携前のOSに戻ると使用できるようになります", "0", "0", "0", "0"},
