[2521] = {2521, "ui_dmm_login9", "他プラットフォームと連携を行う場合は\n所持している原初結晶は連携できません", "0", "0", "0", "0"},
[2522] = {2522, "ui_dmm_login10", "データ連携を行う事で\n複数の端末でハツリバーブ-HAZEREVERB-の\nゲームデータを共有してプレイ出来ます\nデータ連携には<color=#ED6A47>引き続きID</color>と<color=#ED6A47>連携パスワード</color>が必要です。\n<color=#ED6A47>異なるOS</color>にデータ連携した場合、<color=#ED6A47>連携前のOS</color>で所持していた\n<color=#ED6A47>原初結晶は連携後のOSでは使用できません</color>\n連携前のOSに戻ると使用できるようになります", "0", "0", "0", "0"},
